@section('content')<div class="superadmin-heading"><div><p class="superadmin-eyebrow">System Messaging</p><h1>Global Notifications</h1></div><button class="sa-button" onclick="createChannel()">Add channel</button></div><div id="notice" class="sa-notice"></div><section class="sa-card sa-section"><div class="sa-section-header"><div><h2>System channels</h2><p>{{ $channels->total() }} channels</p></div><form method="GET"><input name="q" value="{{ $filters['search'] ?? '' }}" class="sa-input" placeholder="Search channel"><button class="sa-button secondary" type="submit">Filter</button></form></div><div class="sa-table-wrap"><table class="sa-table"><thead><tr><th>Channel</th><th>Type</th><th>Status</th><th>Credential</th><th>Actions</th></tr></thead><tbody>@forelse($channels as $channel)<tr><td><strong>{{ $channel->name }}</strong></td><td>{{ $channel->type }}</td><td>{{ $channel->status }}</td><td>••••••••</td><td><button class="sa-button danger" onclick="deleteChannel({{ $channel->id }})">Delete</button></td></tr>@empty<tr><td colspan="5" class="sa-empty">No global channels.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $channels->links() }}</div></section>@endsection
@push('scripts')<script>async function createChannel(){const name=prompt('Channel name');if(!name)return;const type=prompt('Type','slack');const config=prompt('Credential');if(!type||!config)return;await dfApi('{{ route('superadmin.notifications.store') }}',{method:'POST',body:{name,type,config,status:'active'}});window.location.reload();}async function deleteChannel(id){if(confirm('Delete channel?')){await dfApi(`/superadmin/notifications/${id}`,{method:'DELETE'});window.location.reload();}}</script>@endpush
